VAR
  Overload_Timer : TON;
  Trip_Latched : BOOL;
END_VAR

// Overload protection logic
// Rated current is 41.5 A. Service factor is 1.15.
// Max continuous current = 41.5 * 1.15 = 47.725 A.
// Trip condition: Current > 47.725 A for 5 seconds to allow for minor spikes.

Overload_Timer(IN := Motor_Current > 47.725, PT := T#5S);

IF Overload_Timer.Q THEN
  Trip_Latched := TRUE;
  Overload_Alarm := TRUE;
END_IF;

// Reset logic
IF Fault_Reset THEN
  Trip_Latched := FALSE;
  Overload_Alarm := FALSE;
END_IF;

// Shutdown logic
// Immediate trip if current exceeds 150% rated current (62.25 A) or if latched trip occurs
IF (Motor_Current > 62.25) OR Trip_Latched THEN
  Motor_Stop := TRUE;
ELSE
  Motor_Stop := NOT Start_Command;
END_IF;

